import { listFunctions } from '../../actions/functions/list.js';
import { formatFunctionsList } from '../../utils/display/functions-formatting.js';
import { capitalize, niceId } from '../../utils/display/presenters.js';
import { styleText } from '../../utils/style-text.js';
export async function functionListCore(options) {
    const { auth, flags, log } = options;
    const { scopeId, scopeType } = auth;
    const spinner = flags.json ? undefined : log.ora('Fetching functions...').start();
    const result = await listFunctions(auth, log);
    if (!result.ok) {
        spinner?.fail('Failed to list functions');
        const suggestions = /access|permission|forbidden/i.test(result.error)
            ? [
                `Verify you have access to ${scopeType} "${scopeId}".`,
                'Try a different scope with --project-id or --organization-id.',
            ]
            : undefined;
        return { success: false, error: result.error, suggestions };
    }
    spinner?.stop().clear();
    if (!flags.json) {
        if (result.functions.length === 0) {
            log(`No functions found for ${scopeType} ${niceId(scopeId)}`);
        }
        else {
            log(`${styleText('bold', capitalize(scopeType))} ${niceId(scopeId)} ${styleText('bold', 'Functions')} [${result.functions.length}]:`);
            log(formatFunctionsList(result.functions, { verbose: flags.verbose }));
        }
    }
    return {
        success: true,
        json: { functions: result.functions, scopeType, scopeId },
    };
}
